#!/bin/bash
# check_eol.sh: line endings of tracked text files. Files generated by
# STM32CubeMX must stay CRLF (so regenerating them doesn't rewrite every line);
# everything else we write must be LF. Vendor code (dfm17/Drivers) is skipped.
# No file may mix the two.
cd "$(dirname "$0")/../.." || exit 1

crlf_expected() {
	case "$1" in
	dfm17/.mxproject | dfm17/Core/Startup/*.s) return 0 ;;
	dfm17/Core/Src/main.c | dfm17/Core/Inc/main.h) return 0 ;;
	dfm17/Core/Src/stm32f1xx_it.c | dfm17/Core/Inc/stm32f1xx_it.h) return 0 ;;
	dfm17/Core/Src/stm32f1xx_hal_msp.c | dfm17/Core/Src/system_stm32f1xx.c) return 0 ;;
	dfm17/Core/Inc/stm32f1xx_hal_conf.h) return 0 ;;
	dfm17/Core/Src/dma.c | dfm17/Core/Inc/dma.h | dfm17/Core/Src/gpio.c | dfm17/Core/Inc/gpio.h) return 0 ;;
	dfm17/Core/Src/spi.c | dfm17/Core/Inc/spi.h | dfm17/Core/Src/tim.c | dfm17/Core/Inc/tim.h) return 0 ;;
	dfm17/Core/Src/usart.c | dfm17/Core/Inc/usart.h) return 0 ;;
	esac
	return 1
}

bad=0
while IFS= read -r f; do
	case "$f" in dfm17/Drivers/*) continue ;; esac
	[ -f "$f" ] || continue
	grep -Iq . "$f" || continue		# binary or empty
	total=$(wc -l < "$f")
	cr=$(grep -c $'\r$' "$f")
	if [ "$cr" -ne 0 ] && [ "$cr" -ne "$total" ]; then
		echo "$f: mixed line endings ($cr of $total lines CRLF)"; bad=1
	elif crlf_expected "$f"; then
		[ "$cr" -eq "$total" ] || { echo "$f: generated by STM32CubeMX, must stay CRLF"; bad=1; }
	elif [ "$cr" -ne 0 ]; then
		echo "$f: must be LF"; bad=1
	fi
done < <(git ls-files)
[ $bad -eq 0 ] && echo "line endings OK"
exit $bad
